        // ---------- Zugriff auf die Stofftabellen ----------
        // Lineare Interpolation zwischen den Stuetzstellen (2,5 K Raster).
        // Ausserhalb des Tabellenbereichs wird NICHT extrapoliert, sondern
        // null zurueckgegeben - lieber "Daten fehlen" als eine erfundene Zahl.
        function kmStoff(kaeltemittel, tC) {
            const km = KAELTEMITTEL[kaeltemittel];
            if (!km) return null;
            const tab = km.tabelle;
            if (!tab.length) return null;
            const t = Number(tC);
            if (!Number.isFinite(t) || t < tab[0][0] || t > tab[tab.length - 1][0]) return null;
            let i = 0;
            while (i < tab.length - 2 && tab[i + 1][0] < t) i++;
            const a = tab[i], b = tab[i + 1];
            const f = (b[0] === a[0]) ? 0 : (t - a[0]) / (b[0] - a[0]);
            const ip = k => a[k] + (b[k] - a[k]) * f;
            return {
                t, p: ip(1), rhoFl: ip(2), rhoDa: ip(3), hFl: ip(4), hDa: ip(5),
                cpFl: ip(6), cpDa: ip(7), etaFl: ip(8), etaDa: ip(9),
                pBubble: ip(10),            // Siededruck
                glidBar: ip(10) - ip(1),    // Druckdifferenz Siede-/Taupunkt
                r: ip(5) - ip(4)            // Verdampfungsenthalpie
            };
        }

        // Temperaturgleit in Kelvin: um wie viel liegt der Siedepunkt unter
        // dem Taupunkt beim selben Druck. Wird durch Rueckwaertssuche in der
        // Tabelle bestimmt - keine Extrapolation.
        function kaelteGlideK(kaeltemittel, tDew) {
            const km = KAELTEMITTEL[kaeltemittel];
            if (!km || !km.blend) return 0;
            const s = kmStoff(kaeltemittel, tDew);
            if (!s) return null;
            const zielP = s.p;                   // Taupunktdruck
            const tab = km.tabelle;
            // Temperatur suchen, bei der der SIEDEdruck (Index 10) diesem Druck entspricht
            for (let i = 0; i < tab.length - 1; i++) {
                const a = tab[i], b = tab[i + 1];
                if ((a[10] - zielP) * (b[10] - zielP) <= 0 && a[10] !== b[10]) {
                    const f = (zielP - a[10]) / (b[10] - a[10]);
                    return tDew - (a[0] + (b[0] - a[0]) * f);
                }
            }
            return null;
        }

        function kmListe() {
            return Object.entries(KAELTEMITTEL).map(([k, v]) => ({ key: k, label: v.label, blend: v.blend, tKrit: v.tKrit }));
        }

        // ---------- Kreisprozess: Massenstrom ----------
        // q0 = h1 - h4 mit
        //   h1 = Dampf am Verdichtereintritt (gesaettigt + Sauggasueberhitzung)
        //   h4 = Enthalpie nach der Drossel = Fluessigkeit vor dem EXV
        //        (isenthalpe Drosselung, deshalb identisch)
        function kaelteKreisprozess(p) {
            const { kaeltemittel, tVerdampfung, tVerfluessigung, ueberhitzung = 8, unterkuehlung = 4, kaelteleistungW } = p;
            const hinweise = [];
            const v = kmStoff(kaeltemittel, tVerdampfung);
            const c = kmStoff(kaeltemittel, tVerfluessigung);
            if (!v || !c) {
                return { moeglich: false, hinweise: [`Für ${kaeltemittel} liegen bei ${!v ? tVerdampfung : tVerfluessigung} °C keine Stoffdaten in der Tabelle. ${KAELTEMITTEL[kaeltemittel] ? 'Bereich der Tabelle: ' + KAELTEMITTEL[kaeltemittel].tabelle[0][0] + ' bis ' + KAELTEMITTEL[kaeltemittel].tabelle.slice(-1)[0][0] + ' °C.' : ''} Bei CO₂ oberhalb der kritischen Temperatur ist der Prozess transkritisch und muss gesondert gerechnet werden.`] };
            }
            // Sauggas: gesaettigter Dampf + Ueberhitzung bei konstantem Druck.
            const h1 = v.hDa + v.cpDa * ueberhitzung;
            // Fluessigkeit vor der Drossel: gesaettigt - Unterkuehlung
            const h3 = c.hFl - c.cpFl * unterkuehlung;
            const q0 = h1 - h3;                       // spez. Kaelteleistung kJ/kg
            if (q0 <= 0) return { moeglich: false, hinweise: ['Die spezifische Kälteleistung ist null oder negativ – Verdampfungs- und Verflüssigungstemperatur prüfen.'] };

            const mDot = (kaelteleistungW / 1000) / q0;   // kg/s
            // Sauggasdichte bei Ueberhitzung: Korrektur ueber das ideale
            // Gasgesetz bei konstantem Druck. Naeherung, fuer die Rohr-
            // auslegung ueblich und ausreichend.
            const rhoSaug = v.rhoDa * (v.t + 273.15) / (v.t + ueberhitzung + 273.15);
            // Fluessigkeitsdichte bei Unterkuehlung: Fluessigkeit ist nahezu
            // inkompressibel, Dichte bei Unterkuehlungstemperatur nehmen.
            const cSub = kmStoff(kaeltemittel, tVerfluessigung - unterkuehlung);
            const rhoFluessig = cSub ? cSub.rhoFl : c.rhoFl;
            // Heissgas: Verdichtungsendtemperatur ist ohne Verdichterdaten
            // nicht seriös bestimmbar. Fuer die Druckleitung wird deshalb der
            // gesaettigte Dampf beim Verfluessigungsdruck verwendet und der
            // Wert als konservativ gekennzeichnet.
            const rhoHeissgas = c.rhoDa;

            if (KAELTEMITTEL[kaeltemittel] && KAELTEMITTEL[kaeltemittel].blend) {
                // Glide konkret benennen statt pauschal darauf hinzuweisen.
                // Die Verdampfungstemperatur wird als TAUPUNKT interpretiert -
                // das ist die uebliche Konvention, weil das Sauggas den
                // Verdampfer am Taupunkt verlaesst. Der Siedepunkt am
                // Verdampfereintritt liegt um den Glide tiefer.
                const glidK = kaelteGlideK(kaeltemittel, tVerdampfung);
                hinweise.push({ art: 'pruefen', text: `${kaeltemittel} ist ein zeotropes Gemisch mit ${glidK != null ? 'rund ' + glidK.toFixed(1).replace('.', ',') + ' K' : 'einem'} Temperaturgleit bei ${tVerdampfung} °C. Die angegebene Verdampfungstemperatur wird als Taupunkt am Verdampferaustritt gerechnet; am Verdampfereintritt liegt die Temperatur entsprechend tiefer. Für die endgültige Auslegung das Herstellerdatenblatt verwenden.` });
            }
            hinweise.push({ art: 'info', text: 'Die Heißgasdichte wird mit gesättigtem Dampf beim Verflüssigungsdruck gerechnet – ohne Verdichterdaten ist die Verdichtungsendtemperatur nicht bestimmbar. Das ergibt eine eher großzügige Druckleitung.' });

            return {
                moeglich: true, hinweise,
                kaeltemittel, tSat: tVerdampfung, tSatHoch: tVerfluessigung,
                q0, mDot, mDotKgH: mDot * 3600,
                pVerdampfung: v.p, pVerfluessigung: c.p, druckverhaeltnis: c.p / v.p,
                rhoSaug, rhoFluessig, rhoHeissgas,
                etaSaug: v.etaDa, etaFluessig: (cSub || c).etaFl, etaHeissgas: c.etaDa,
                volumenstromSaug: (mDot / rhoSaug) * 3600,        // m³/h
                volumenstromFluessig: (mDot / rhoFluessig) * 3600,
                volumenstromHeissgas: (mDot / rhoHeissgas) * 3600
            };
        }

        // ---------- Kupferrohr-Dimensionen ----------
        // Aussendurchmesser × Wandstaerke in mm, uebliche Kaeltetechnik-
        // Abmessungen (metrisch). Innendurchmesser = da - 2×s.
        const KUPFERROHRE = [
            [6, 1.0], [8, 1.0], [10, 1.0], [12, 1.0], [15, 1.0], [16, 1.0], [18, 1.0],
            [22, 1.0], [28, 1.0], [35, 1.5], [42, 1.5], [54, 2.0], [64, 2.0], [76.1, 2.0], [88.9, 2.0], [108, 2.5]
        ].map(([da, s]) => ({ da, s, di: da - 2 * s, bez: `Ø ${da} × ${s} mm` }));

        // Aequivalente Rohrlaengen fuer Formstuecke als Vielfaches des
        // Innendurchmessers. Uebliche Auslegungswerte der Kaeltetechnik.
        // Herstellerangaben haben Vorrang, wenn vorhanden.
        const FORMSTUECK_LD = {
            bogen90: 30, bogen45: 16, tStueckDurchgang: 20, tStueckAbzweig: 60,
            ventil: 90, rueckschlagventil: 100, magnetventil: 110, filtertrockner: 120, schauglas: 20
        };

        function kaelteAequivalenteLaenge(formstuecke, diMm) {
            const di = diMm / 1000;
            let l = 0; const detail = [];
            for (const [key, anzahl] of Object.entries(formstuecke || {})) {
                const ld = FORMSTUECK_LD[key];
                if (!ld || !anzahl) continue;
                const teil = ld * di * anzahl;
                l += teil;
                detail.push(`${anzahl}× ${key} = ${teil.toFixed(1)} m`);
            }
            return { laenge: l, detail };
        }

        // ---------- Druckverlust einer Leitung ----------
        // Darcy-Weisbach mit Colebrook-White (iterativ geloest).
        function kaelteRohrReibungszahl(re, diMm, rauheitMm = 0.0015) {
            if (re < 2300) return 64 / Math.max(1, re);          // laminar
            const rel = rauheitMm / diMm;
            let f = 0.02;
            for (let i = 0; i < 40; i++) {
                const neu = 1 / Math.pow(-2 * Math.log10(rel / 3.7 + 2.51 / (re * Math.sqrt(f))), 2);
                if (Math.abs(neu - f) < 1e-9) { f = neu; break; }
                f = neu;
            }
            return f;
        }

        // Berechnet eine konkrete Rohrdimension durch.
        //  art: 'saug' | 'fluessig' | 'heissgas'
        function kaelteLeitung(rohr, art, kp, geo) {
            const rho = art === 'fluessig' ? kp.rhoFluessig : art === 'heissgas' ? kp.rhoHeissgas : kp.rhoSaug;
            const eta = (art === 'fluessig' ? kp.etaFluessig : art === 'heissgas' ? kp.etaHeissgas : kp.etaSaug) * 1e-6; // Pa·s
            const di = rohr.di / 1000;                       // m
            const flaeche = Math.PI * di * di / 4;           // m²
            const w = (kp.mDot / rho) / flaeche;             // m/s
            const re = rho * w * di / eta;
            const f = kaelteRohrReibungszahl(re, rohr.di);
            const aeq = kaelteAequivalenteLaenge(geo.formstuecke, rohr.di);
            const lGesamt = (geo.laenge || 0) + aeq.laenge;
            const dpReibung = f * (lGesamt / di) * (rho * w * w / 2);   // Pa

            // Statische Hoehe: bei der Fluessigkeitsleitung gewinnt eine
            // fallende Leitung Druck, eine steigende verliert. Beim Sauggas
            // ist der Anteil wegen der geringen Dichte meist vernachlaessigbar,
            // wird aber trotzdem mitgerechnet.
            const dpHoehe = rho * 9.81 * (geo.hoehenunterschied || 0);
            const dpGesamt = dpReibung + dpHoehe;

            return {
                rohr, w, re, f, aeqLaenge: aeq.laenge, aeqDetail: aeq.detail, lGesamt,
                dpReibungBar: dpReibung / 1e5, dpHoeheBar: dpHoehe / 1e5, dpGesamtBar: dpGesamt / 1e5,
                rho, volumenInnenL: flaeche * (geo.laenge || 0) * 1000
            };
        }

        // ---------- Mindestgeschwindigkeit fuer den Oeltransport ----------
        // Konkret berechnet statt pauschal "bitte pruefen".
        // Grundlage: das Gas muss den Oelfilm mitreissen. Massgebend ist das
        // Verhaeltnis von Traegheitskraft zu Schwerkraft - eine Froude-Zahl:
        //     w_min = Fr · sqrt( g · di · (rhoFl − rhoDa) / rhoDa )
        // Dadurch steigt die Mindestgeschwindigkeit mit dem Rohrdurchmesser,
        // genau wie es die Praxisliteratur beschreibt ("in Steigleitungen
        // kriecht das Oel an der Innenwand hoch, je groesser das Rohr, desto
        // hoeher muss die Geschwindigkeit in der Rohrmitte sein").
        // Fr-Werte so gewaehlt, dass die Formel die seit Jahrzehnten bewaehrten
        // Nennwerte reproduziert:
        //   Steigleitung  1500 fpm = 7,6 m/s     waagrecht 700-800 fpm = 3,6-4,1 m/s
        // Zusaetzlich wirkt dieser Nennwert als absolute Untergrenze, damit die
        // Formel bei sehr kleinen Rohren nicht unter die Praxiswerte faellt.
        // Quellen: Refrigeration World "Basics of Refrigerant Piping";
        // Lennox Application and Design Guidelines (Refrigerant Piping Manual).
        const OEL_FROUDE = { steigend: 1.0, waagrecht: 0.45 };
        const OEL_NENN_MS = { steigend: 6.1, waagrecht: 3.6 };

        function kaelteOelMindestgeschwindigkeit(rhoFl, rhoDa, diMm, steigend) {
            const di = diMm / 1000;
            const fr = steigend ? OEL_FROUDE.steigend : OEL_FROUDE.waagrecht;
            const froude = fr * Math.sqrt(9.81 * di * Math.max(0.001, (rhoFl - rhoDa)) / Math.max(0.001, rhoDa));
            const nenn = steigend ? OEL_NENN_MS.steigend : OEL_NENN_MS.waagrecht;
            return {
                wMin: Math.max(froude, nenn),
                ausFroude: froude, ausNennwert: nenn,
                massgebend: froude >= nenn ? 'Froude-Kriterium (Rohrdurchmesser)' : 'bewährter Nennwert'
            };
        }

        // Bewertungsgrenzen fuer die Stroemungsgeschwindigkeit [m/s].
        // Uebliche Auslegungsbereiche der Kaeltetechnik - keine Norm.
        // Saugleitung waagrecht braucht Mindestgeschwindigkeit fuer den
        // Oelrueckfluss, Steigleitungen deutlich mehr.
        const STROEMUNG_GRENZEN = {
            saug:     { min: 4, minSteig: 8, max: 15, opt: [6, 12] },
            heissgas: { min: 4, minSteig: 8, max: 18, opt: [8, 15] },
            // Fluessigkeitsleitung: enger gefasst (2026-09). Ueber etwa
            // 1,2 m/s steigt der Druckverlust so stark, dass die Unterkuehlung
            // aufgezehrt wird und vor dem Expansionsventil Flashgas entsteht -
            // die Leitung ist dann zu klein, auch wenn "es fliesst".
            fluessig: { min: 0, minSteig: 0, max: 1.2, opt: [0.3, 1.0] }
        };

        // Rechnet einen Druckverlust in den zugehoerigen Verlust an
        // Saettigungstemperatur um. Das ist das Mass, das in der Kaeltetechnik
        // zaehlt: 0,3 bar sind bei CO2 kaum etwas, bei R134a viel.
        // Wird aus der Stofftabelle gelesen, nicht ueber eine Faustformel.
        function kaelteDruckverlustK(kaeltemittel, tSat, dpBar, seiteSaug = true) {
            const s = kmStoff(kaeltemittel, tSat);
            if (!s || !(dpBar > 0)) return 0;
            const km = KAELTEMITTEL[kaeltemittel];
            const zielP = seiteSaug ? s.p - dpBar : s.p + dpBar;
            if (zielP <= 0) return null;
            const tab = km.tabelle;
            for (let i = 0; i < tab.length - 1; i++) {
                const a = tab[i], b = tab[i + 1];
                if ((a[1] - zielP) * (b[1] - zielP) <= 0 && a[1] !== b[1]) {
                    const f = (zielP - a[1]) / (b[1] - a[1]);
                    return Math.abs(tSat - (a[0] + (b[0] - a[0]) * f));
                }
            }
            return null;   // ausserhalb der Tabelle - nicht extrapolieren
        }

        // Zulaessiger Temperaturverlust je Leitung [K]. Uebliche Auslegung.
        const DRUCKVERLUST_GRENZE_K = { saug: 1.5, heissgas: 1.0, fluessig: 1.0 };

        // Vergleicht alle Rohrdimensionen und empfiehlt eine.
        function kaelteRohrAuswahl(art, kp, geo) {
            if (!kp.moeglich) return { moeglich: false, hinweise: kp.hinweise };
            const g = STROEMUNG_GRENZEN[art];
            const steigend = (geo.hoehenunterschied || 0) > 0.5;
            const varianten = KUPFERROHRE.map(r => {
                const e = kaelteLeitung(r, art, kp, geo);
                const bewertung = [];
                let ok = true;
                if (e.w > g.max) { bewertung.push({ art: 'fehler', text: `Strömung ${e.w.toFixed(1)} m/s über dem Grenzwert ${g.max} m/s – Geräusch und Druckverlust zu hoch.` }); ok = false; }
                else if (e.w > g.opt[1]) bewertung.push({ art: 'warnung', text: `Strömung ${e.w.toFixed(1)} m/s über dem üblichen Bereich.` });
                let oel = null;
                if (art !== 'fluessig') {
                    // Fuer Gasleitungen die Mindestgeschwindigkeit konkret rechnen.
                    const rhoFl = kp.rhoFluessig;
                    oel = kaelteOelMindestgeschwindigkeit(rhoFl, e.rho, r.di, steigend);
                    if (e.w < oel.wMin) { bewertung.push({ art: 'fehler', text: `Strömung ${e.w.toFixed(1)} m/s liegt unter der berechneten Mindestgeschwindigkeit ${oel.wMin.toFixed(1)} m/s für den Öltransport (${steigend ? 'Steigleitung' : 'waagrecht'}, Ø ${r.di.toFixed(1)} mm innen, maßgebend: ${oel.massgebend}). Öl kehrt nicht sicher zum Verdichter zurück – kleinere Dimension wählen.` }); ok = false; }
                    else if (e.w < oel.wMin * 1.25) bewertung.push({ art: 'warnung', text: `Strömung ${e.w.toFixed(1)} m/s liegt nur knapp über der Mindestgeschwindigkeit ${oel.wMin.toFixed(1)} m/s. Bei Teillast (geregelter Verdichter) reicht das nicht mehr – dann Doppelsteigleitung oder Leistungsregelung berücksichtigen.` });
                    // Teillast-Reserve: bei halber Leistung halbiert sich die Geschwindigkeit.
                    if (ok && e.w / 2 < oel.wMin) bewertung.push({ art: 'info', text: `Bei 50 % Teillast fällt die Strömung auf ${(e.w / 2).toFixed(1)} m/s und liegt damit unter ${oel.wMin.toFixed(1)} m/s. Für geregelte Anlagen Doppelsteigleitung prüfen.` });
                } else if (e.w > g.opt[1]) bewertung.push({ art: 'warnung', text: `Flüssigkeitsgeschwindigkeit ${e.w.toFixed(2)} m/s über dem üblichen Bereich (${g.opt[0]}–${g.opt[1]} m/s) – Druckverlust erhöht die Flashgas-Gefahr vor dem Expansionsventil. Unterkühlung prüfen oder größere Dimension wählen.` });
                // Druckverlust in Temperaturverlust umrechnen und bewerten.
                // Eine Leitung, die den Oeltransport schafft, aber 1 bar
                // Druckverlust hat, ist trotzdem zu klein.
                let dTv = null;
                if (kp.kaeltemittel && kp.tSat != null) {
                    dTv = kaelteDruckverlustK(kp.kaeltemittel, art === 'saug' ? kp.tSat : kp.tSatHoch, e.dpGesamtBar, art === 'saug');
                    const grenze = DRUCKVERLUST_GRENZE_K[art];
                    if (dTv != null && dTv > grenze) {
                        bewertung.push({ art: 'fehler', text: `Druckverlust ${e.dpGesamtBar.toFixed(3).replace('.', ',')} bar entspricht ${dTv.toFixed(1).replace('.', ',')} K Temperaturverlust – zulässig sind ${grenze.toFixed(1).replace('.', ',')} K. Das kostet Leistung, ${art === 'fluessig' ? 'zehrt die Unterkühlung auf und erzeugt Flashgas' : 'die Leitung ist zu klein'}.` });
                        ok = false;
                    } else if (dTv != null && dTv > grenze * 0.7) {
                        bewertung.push({ art: 'warnung', text: `Temperaturverlust ${dTv.toFixed(1).replace('.', ',')} K liegt nahe an der Grenze von ${grenze.toFixed(1).replace('.', ',')} K.` });
                    }
                }
                return { ...e, ok, bewertung, oel, dTverlustK: dTv };
            });
            // Empfehlung: kleinste Dimension, die alle harten Kriterien erfuellt
            const geeignet = varianten.filter(v => v.ok);
            const empfehlung = geeignet.length ? geeignet[0] : null;
            return { moeglich: true, art, steigend, varianten, empfehlung, hinweise: kp.hinweise };
        }

        // ---------- Isolierstärke gegen Kondensat ----------
        // Kriterium: die Oberflaeche der Daemmung muss waermer bleiben als der
        // Taupunkt der Umgebungsluft, sonst schwitzt die Leitung.
        //   R_daemm  = ln(da/di) / (2·π·λ)          [mK/W]
        //   R_ober   = 1 / (π·da·h)                  [mK/W]
        //   q        = (t_umg − t_rohr) / (R_daemm + R_ober)
        //   t_ober   = t_umg − q · R_ober
        // Gefordert: t_ober ≥ Taupunkt + Sicherheitsabstand.
        // λ und h sind Katalog- bzw. Erfahrungswerte und stehen hier oben,
        // damit sie nachvollziehbar bleiben.
        const DAEMM_LAMBDA = { 'Elastomer (Armaflex o. ä.)': 0.036, 'PE-Schaum': 0.040, 'Kautschuk hochwertig': 0.033 };
        const DAEMM_STAERKEN = [9, 13, 19, 25, 32, 40, 50, 60];
        const DAEMM_H_AUSSEN = 9;      // W/m²K, ruhende Innenluft inkl. Strahlung
        const DAEMM_SICHERHEIT_K = 1;  // K Abstand zum Taupunkt

        function kaelteIsolierung(p) {
            const { rohrAussenMm, tRohr, tUmgebung = 25, rhUmgebung = 70, material = 'Elastomer (Armaflex o. ä.)' } = p;
            const lambda = DAEMM_LAMBDA[material] ?? 0.036;
            const taupunkt = kaelteTaupunkt(tUmgebung, rhUmgebung);
            const di = rohrAussenMm / 1000;
            const dT = tUmgebung - tRohr;

            const varianten = DAEMM_STAERKEN.map(s => {
                const da = di + 2 * (s / 1000);
                const rDaemm = Math.log(da / di) / (2 * Math.PI * lambda);
                const rOber = 1 / (Math.PI * da * DAEMM_H_AUSSEN);
                const q = dT / (rDaemm + rOber);            // W/m
                const tOber = tUmgebung - q * rOber;
                return {
                    staerke: s, waermestromWm: q, oberflaeche: tOber,
                    trocken: tOber >= taupunkt + DAEMM_SICHERHEIT_K,
                    reserve: tOber - taupunkt
                };
            });
            const empfehlung = varianten.find(v => v.trocken) || null;
            return {
                taupunkt, lambda, material, varianten, empfehlung,
                hinweis: empfehlung
                    ? `Bei ${tUmgebung} °C und ${rhUmgebung} % rel. Feuchte liegt der Taupunkt bei ${taupunkt.toFixed(1)} °C. ${empfehlung.staerke} mm halten die Oberfläche auf ${empfehlung.oberflaeche.toFixed(1)} °C – ${empfehlung.reserve.toFixed(1)} K über dem Taupunkt.`
                    : `Auch ${DAEMM_STAERKEN[DAEMM_STAERKEN.length - 1]} mm reichen bei ${tUmgebung} °C und ${rhUmgebung} % nicht aus. Umgebungsfeuchte senken, Doppeldämmung oder Begleitheizung prüfen.`
            };
        }

        // ---------- Kältemittelfüllmenge ----------
        // Wird aus der tatsaechlichen Anlagengeometrie gerechnet, nicht
        // geschaetzt: je Leitung Innenvolumen × Dichte im jeweiligen Zustand.
        // Fuer Verdampfer, Verflüssiger und Sammler gibt es KEINE Schaetzung -
        // deren Innenvolumen steht nur im Herstellerdatenblatt. Fehlt es,
        // wird das offen ausgewiesen statt eine Zahl zu erfinden.
        function kaelteFuellmenge(leitungen, kp, bauteilVolumenL = {}) {
            const teile = [];
            const offen = [];
            let gesamt = 0;

            const dichte = { fluessig: kp.rhoFluessig, saug: kp.rhoSaug, heissgas: kp.rhoHeissgas };
            const label = { fluessig: 'Flüssigkeitsleitung', saug: 'Saugleitung', heissgas: 'Druckleitung' };

            (leitungen || []).forEach(l => {
                if (!l.diMm || !l.laenge) return;
                const di = l.diMm / 1000;
                const volL = (Math.PI * di * di / 4) * l.laenge * 1000;   // Liter
                const rho = dichte[l.art] || 0;
                // Die Saugleitung fuehrt Dampf, dort ist die Fuellmenge klein.
                // Die Fluessigkeitsleitung dominiert die Fuellmenge deutlich.
                const kg = volL / 1000 * rho;
                gesamt += kg;
                teile.push({ name: `${label[l.art] || l.art}${l.bez ? ' ' + l.bez : ''}`, volumenL: volL, dichte: rho, kg,
                    formel: `${volL.toFixed(2)} l × ${rho.toFixed(1)} kg/m³` });
            });

            // Bauteile: nur rechnen, wenn ein Innenvolumen bekannt ist.
            [['verdampfer', 'Verdampfer', 'fluessig'], ['verfluessiger', 'Verflüssiger / Gaskühler', 'fluessig'],
             ['sammler', 'Flüssigkeitssammler', 'fluessig'], ['sonstige', 'Sonstige Bauteile', 'fluessig']].forEach(([key, name, zustand]) => {
                const v = Number(bauteilVolumenL[key]);
                if (!v) { offen.push(name); return; }
                // Verdampfer und Verfluessiger sind im Betrieb nur teilweise
                // fluessig gefuellt. Ohne Herstellerangabe zum Fuellgrad wird
                // mit einem klar benannten Fuellgrad gerechnet.
                const fuellgrad = (key === 'sammler') ? 0.6 : (key === 'sonstige' ? 1.0 : 0.35);
                const kg = v / 1000 * kp.rhoFluessig * fuellgrad;
                gesamt += kg;
                teile.push({ name, volumenL: v, dichte: kp.rhoFluessig, kg,
                    formel: `${v} l × ${kp.rhoFluessig.toFixed(1)} kg/m³ × ${(fuellgrad * 100).toFixed(0)} % Füllgrad` });
            });

            return {
                teile, gesamt, offen,
                sicher: offen.length === 0,
                hinweis: offen.length
                    ? `Für ${offen.join(', ')} ist kein Innenvolumen hinterlegt. Diese Anteile fehlen in der Summe – Innenvolumen aus dem Herstellerdatenblatt eintragen.`
                    : 'Alle Anteile aus tatsächlichen Volumina gerechnet. Füllgrade von Verdampfer und Verflüssiger sind Annahmen – Herstellerangabe hat Vorrang.'
            };
        }

        // ---------- Verdichterkombinationen ----------
        // Vergleicht, wie sich die Gesamtlast auf mehrere Verdichter aufteilen
        // laesst. Rechnet KEINE Herstellerdaten - es geht um Stufigkeit,
        // Regelbereich und Reserve. Welcher konkrete Verdichter das leistet,
        // entscheidet das Datenblatt.
        //
        // Zwei Bauformen werden verglichen:
        //   gleich   alle Verdichter gleich gross
        //   gestuft  ein kleinerer Grundlastverdichter (halbe Groesse)
        //            -> feinere unterste Stufe, besseres Teillastverhalten
        function kaelteVerdichterKombinationen(bedarfKW, opts = {}) {
            const reserve = opts.reserve != null ? opts.reserve : 0.10;   // 10 % Auslegungsreserve
            const minLast = opts.minLastKW != null ? opts.minLastKW : bedarfKW * 0.25;
            const ziel = bedarfKW * (1 + reserve);
            const ergebnisse = [];

            for (let n = 1; n <= 4; n++) {
                // a) gleich grosse Verdichter
                const einzel = ziel / n;
                const stufenGleich = Array.from({ length: n }, (_, i) => (i + 1) * einzel);
                ergebnisse.push(bewerte('gleich', n, stufenGleich, einzel, ziel, bedarfKW, minLast));

                // b) gestuft: erster Verdichter halb so gross
                if (n >= 2) {
                    const gross = ziel / (n - 0.5);
                    const klein = gross / 2;
                    const stufen = [];
                    // alle erreichbaren Kombinationen aufsteigend
                    for (let k = 0; k <= 1; k++) {
                        for (let g = 0; g <= n - 1; g++) {
                            const s = k * klein + g * gross;
                            if (s > 0) stufen.push(Math.round(s * 100) / 100);
                        }
                    }
                    stufen.sort((x, y) => x - y);
                    ergebnisse.push(bewerte('gestuft', n, [...new Set(stufen)], klein, ziel, bedarfKW, minLast));
                }
            }

            function bewerte(bauform, anzahl, stufen, kleinsteStufe, ziel, bedarf, minLast) {
                const max = Math.max(...stufen);
                const min = Math.min(...stufen);
                const regelbereich = max > 0 ? (1 - min / max) * 100 : 0;
                const auslastung = max > 0 ? (bedarf / max) * 100 : 0;
                const bewertung = [];
                let punkte = 100;
                if (min > minLast * 1.15) {
                    bewertung.push({ art: 'warnung', text: `Kleinste Stufe ${min.toFixed(2).replace('.', ',')} kW liegt über der erwarteten Mindestlast von ${minLast.toFixed(2).replace('.', ',')} kW – bei schwacher Last taktet die Anlage.` });
                    punkte -= 30;
                }
                if (auslastung > 98) { bewertung.push({ art: 'fehler', text: 'Keine Reserve – die Anlage läuft dauerhaft am Anschlag.' }); punkte -= 50; }
                else if (auslastung < 55) { bewertung.push({ art: 'warnung', text: `Nur ${auslastung.toFixed(0)} % Auslastung – deutlich überdimensioniert.` }); punkte -= 25; }
                if (anzahl === 1) { bewertung.push({ art: 'warnung', text: 'Ein einzelner Verdichter: keine Redundanz, bei Ausfall steht die Anlage.' }); punkte -= 15; }
                if (anzahl >= 4) { bewertung.push({ art: 'info', text: 'Vier Verdichter bedeuten mehr Regelgüte, aber auch mehr Wartung, Ölmanagement und Kosten.' }); punkte -= 10; }
                punkte += Math.min(20, regelbereich / 5);
                return {
                    bauform, anzahl, stufen, kleinsteStufe, maxLeistung: max, minStufe: min,
                    regelbereich, auslastung, reserveKW: max - bedarf, bewertung, punkte,
                    beschreibung: bauform === 'gleich'
                        ? `${anzahl} × ${(ziel / anzahl).toFixed(2).replace('.', ',')} kW`
                        : `1 × ${(kleinsteStufe).toFixed(2).replace('.', ',')} kW + ${anzahl - 1} × ${(kleinsteStufe * 2).toFixed(2).replace('.', ',')} kW`
                };
            }

            ergebnisse.sort((x, y) => y.punkte - x.punkte);
            return { ziel, bedarfKW, reserve, minLast, varianten: ergebnisse, empfehlung: ergebnisse[0] || null };
        }
